ENDPOINT_TABLES = {"income": PT_INCOME, "balancesheet": PT_BALANCE, "cashflow": PT_CASHFLOW}


def to_rquant(code):
    return code[:-3] + ".SH" if code.endswith(".SS") else code


def _chunks(codes, size):
    for first in range(0, len(codes), size):
        yield codes[first:first + size]


def _day(value):
    return pd.Timestamp(str(value).replace("-", "")[:8])


def trading_calendar(end):
    """Exchange trading days from 2005 through ``end`` (YYYYMMDD)."""
    days = pd.DatetimeIndex([_day(day) for day in get_trade_days(CALENDAR_START, end)])  # noqa: F821
    return days[days <= _day(end)]


def sh_main_codes(end):
    return sorted(code for code in get_Ashares(end) if code.startswith("60") and code.endswith(".SS"))  # noqa: F821


def all_a_codes(end):
    return sorted(code for code in get_Ashares(end) if code.endswith(".SS") or code.endswith(".SZ"))  # noqa: F821


def _bars(codes, fields, start, end, calendar):
    """Yield (code, dates, structured array) of unadjusted daily bars on exchange trading days, oldest first."""
    for chunk in _chunks(codes, BAR_CHUNK):
        data = get_price(chunk, start_date=start, end_date=end, frequency="1d", fields=fields,  # noqa: F821
                         fq=None, is_dict=True) or {}
        for code in chunk:
            bars = data.get(code)
            if bars is None or len(bars) == 0:
                continue
            dates = pd.DatetimeIndex([_day(value) for value in bars["datetime"]])
            keep = dates.isin(calendar) & ~dates.duplicated(keep="last")
            yield code, dates[keep], bars[keep]


def _traded(bars):
    return (np.asarray(bars["volume"], dtype=float) > 0) & (np.asarray(bars["close"], dtype=float) > 0)


def canonical_factor(close, pre_close, traded):
    """RQuant's canonical factor per bar, or None when the stock never traded (see qmt_inputs.canonical_factor)."""
    close = np.asarray(close, dtype=float)
    pre_close = np.asarray(pre_close, dtype=float)
    previous = np.r_[np.nan, close[:-1]]
    step = np.ones(len(close))
    usable = (previous > 0) & (pre_close > 0)
    step[usable] = previous[usable] / pre_close[usable]
    adj = np.cumprod(step)
    first = np.flatnonzero(traded)
    if not len(first):
        return None
    first = first[0]
    return adj / (adj[first] * close[first])


def price_panels(codes, dates, end, calendar):
    """Canonical and raw daily panels on ``dates``; days without a traded bar are missing."""
    names = ("open", "high", "low", "close", "volume", "amount", "raw_close", "raw_volume", "raw_open",
             "raw_pre_close", "factor")
    columns = dict((name, {}) for name in names)
    for code, index, bars in _bars(codes, BAR_FIELDS, DATA_START, end, calendar):
        traded = _traded(bars)
        factor = canonical_factor(bars["close"], bars["preclose"], traded)
        if factor is None:
            continue
        keep = traded & index.isin(dates)
        at = index[keep]
        factor = factor[keep]
        raw = dict((field, np.asarray(bars[field], dtype=float)[keep]) for field in BAR_FIELDS)
        for field in ("open", "high", "low", "close"):
            columns[field][code] = pd.Series(raw[field] * factor, index=at)
        columns["volume"][code] = pd.Series(raw["volume"] / factor, index=at)
        columns["amount"][code] = pd.Series(raw["money"], index=at)
        columns["raw_close"][code] = pd.Series(raw["close"], index=at)
        columns["raw_volume"][code] = pd.Series(raw["volume"], index=at)
        columns["raw_open"][code] = pd.Series(raw["open"], index=at)
        columns["raw_pre_close"][code] = pd.Series(raw["preclose"], index=at)
        columns["factor"][code] = pd.Series(factor, index=at)
    return dict((name, pd.DataFrame(values).reindex(index=dates, columns=codes)) for name, values in columns.items())


def _cacheable(dates):
    """Days whose answers may be kept for later runs: all but the last CACHE_RECENT_DAYS (they may still change)."""
    return set(dates[:-CACHE_RECENT_DAYS]) if len(dates) > CACHE_RECENT_DAYS else set()


def valuation_panels(codes, dates, fields, log=print, cache=None):
    """{field: dates x codes} from PTrade's daily valuation table; gaps take the stock's nearest known value.

    ``cache`` (a dict kept between runs, as a live strategy left running does) holds the answers of earlier days, so a
    later run only asks for the days it has not seen.
    """
    values = dict((field, {}) for field in fields)
    store = cache.setdefault(("valuation",) + tuple(fields), {}) if cache is not None else {}
    keep = _cacheable(dates)
    began, asked = time.time(), 0
    for number, day in enumerate(dates):
        if day in store:
            for field in fields:
                if field in store[day]:
                    values[field][day] = store[day][field]
            continue
        asked += 1
        stamp = day.strftime("%Y%m%d")
        for chunk in _chunks(codes, VALUATION_CHUNK):
            frame = None
            for attempt in range(3):
                try:
                    frame = get_fundamentals(chunk, "valuation", fields, date=stamp)  # noqa: F821
                except Exception:
                    frame = None
                if frame is not None and len(frame):
                    break
                time.sleep(0.5)
            if frame is None or not len(frame):
                continue
            if "secu_code" in frame.columns:
                frame = frame.set_index("secu_code")
            for field in fields:
                if field in frame.columns:
                    values[field][day] = pd.to_numeric(frame[field], errors="coerce").combine_first(
                        values[field].get(day, pd.Series(dtype=float)))
        if day in keep and any(day in values[field] for field in fields):
            store[day] = dict((field, values[field][day]) for field in fields if day in values[field])
        if number and number % 200 == 0:
            log("inputs.valuation_progress", "%d/%d days %.0fs" % (number, len(dates), time.time() - began))
    if cache is not None:
        log("inputs.valuation_asked_days", "%d of %d" % (asked, len(dates)))
    panels = {}
    for field in fields:
        panel = pd.DataFrame(values[field]).T.reindex(index=dates, columns=codes)
        panels[field] = panel.where(panel > 0).ffill().bfill()
    return panels


def _statement_table(codes, table, fields, start_year, end_year, log=print):
    """One table's rows as a frame with columns secu_code, end_date, publ_date and ``fields``."""
    parts, missing = [], set(fields)
    for chunk in _chunks(codes, STATEMENT_CODES):
        for first in range(0, len(fields), STATEMENT_FIELDS_PER_CALL):
            wanted = fields[first:first + STATEMENT_FIELDS_PER_CALL]
            frame = None
            for attempt in range(3):
                try:
                    frame = get_fundamentals(chunk, table, wanted, start_year=str(start_year),  # noqa: F821
                                             end_year=str(end_year))
                except Exception as exc:
                    log("inputs.statement_retry", "%s %s" % (table, exc))
                    frame = None
                if frame is not None:
                    break
                time.sleep(1.0)
            if frame is None or not len(frame):
                continue
            frame = frame.reset_index()
            missing -= set(frame.columns)
            keys = [name for name in ("secu_code", "end_date", "publ_date") if name in frame.columns]
            parts.append(frame[keys + [name for name in wanted if name in frame.columns]])
    if missing:
        log("inputs.statement_missing_fields", "%s %s" % (table, sorted(missing)))
    if not parts:
        return pd.DataFrame(columns=["secu_code", "end_date", "publ_date"] + list(fields))
    frame = pd.concat(parts, ignore_index=True)
    frame = frame.groupby(["secu_code", "end_date"], as_index=False).first()
    return frame


def fundamentals_frame(codes, start_year, end_year, log=print):
    """One row per stock and quarter end in Tushare column names, as rquant's fundamentals.parquet."""
    names = [name for endpoint in ("income", "balancesheet", "cashflow") for name in PTRADE_FIELDS[endpoint]]
    merged = None
    absent = []
    for endpoint, mapping in PTRADE_FIELDS.items():
        table = ENDPOINT_TABLES[endpoint]
        fields = sorted(set(field for field in mapping.values() if field is not None))
        absent += [name for name, field in mapping.items() if field is None]
        frame = _statement_table(codes, table, fields, start_year, end_year, log)
        frame = frame.rename(columns={"publ_date": "publ_" + endpoint})
        out = frame[["secu_code", "end_date", "publ_" + endpoint]].copy()
        for name, field in mapping.items():
            if field is not None:
                out[name] = pd.to_numeric(frame[field], errors="coerce") if field in frame.columns else np.nan
        merged = out if merged is None else merged.merge(out, on=["secu_code", "end_date"], how="outer")
    published = merged[["publ_" + endpoint for endpoint in PTRADE_FIELDS]].apply(
        lambda column: pd.to_datetime(column, errors="coerce"))
    merged["ann_date"] = published.min(axis=1)
    merged["end_date"] = pd.to_datetime(merged["end_date"], errors="coerce")
    merged = merged[merged["ann_date"].notna() & merged["end_date"].notna()]
    for name in absent:
        merged[name] = 0.0
    merged = merged.rename(columns={"secu_code": "instrument"})
    merged = merged.sort_values(["instrument", "end_date"]).reset_index(drop=True)
    return merged[["instrument", "end_date", "ann_date"] + names]


def listing_dates(codes):
    info = get_stock_info(codes, ["listed_date"]) or {}  # noqa: F821
    opened = {}
    for code in codes:
        value = str((info.get(code) or {}).get("listed_date") or "")
        opened[code] = _day(value) if len(value) >= 8 else pd.NaT
    return opened


def market_return(codes, dates, end, calendar, opened, floats):
    """Circulating-cap-weighted all-A return, as rquant.data.reference's ``mkt``."""
    start = calendar[max(calendar.searchsorted(dates[0]) - 1, 0)]
    window = calendar[(calendar >= start) & (calendar <= dates[-1])]
    closes, returns = {}, {}
    for code, index, bars in _bars(codes, ["close", "preclose", "volume"], start.strftime("%Y%m%d"), end, calendar):
        traded = _traded(bars)
        close = np.asarray(bars["close"], dtype=float)[traded]
        pre_close = np.asarray(bars["preclose"], dtype=float)[traded]
        safe = np.where(pre_close > 0, pre_close, np.nan)
        closes[code] = pd.Series(close, index=index[traded])
        returns[code] = pd.Series(close / safe - 1.0, index=index[traded])
    codes = sorted(closes)
    close = pd.DataFrame(closes).reindex(index=window, columns=codes)
    ret = pd.DataFrame(returns).reindex(index=window, columns=codes)
    shares = floats.reindex(index=window, columns=codes).ffill().bfill()
    # The previous trading day's circulating cap, as reference.py weights by the previous daily_basic.
    weights = (close * shares).shift(1)
    listed = pd.DatetimeIndex([opened.get(code, pd.NaT) for code in codes])
    age = (window.values[:, None] - listed.values[None, :]).astype("timedelta64[D]").astype(float)
    seasoned = pd.DataFrame((age >= MARKET_SEASONING_DAYS) & ~np.isnan(age), index=window, columns=codes)
    valid = ret.notna() & (weights > 0) & seasoned
    count = valid.sum(axis=1)
    weighted = (ret.where(valid) * weights.where(valid)).sum(axis=1) / weights.where(valid).sum(axis=1)
    return weighted.where(count >= MARKET_MIN_STOCKS).reindex(dates), count.reindex(dates)


def status_panel(codes, dates, kind, log=print, cache=None):
    """dates x codes booleans from get_stock_status(codes, kind, date) (kind 'ST' or 'DELISTING'); ``cache`` as in
    valuation_panels."""
    rows = {}
    store = cache.setdefault(("status", kind), {}) if cache is not None else {}
    keep = _cacheable(dates)
    for day in dates:
        known = store.get(day, {})
        wanted = [code for code in codes if code not in known]
        flags = {}
        if wanted:
            try:
                flags = get_stock_status(wanted, kind, day.strftime("%Y%m%d")) or {}  # noqa: F821
            except Exception as exc:
                log("inputs.status_error", "%s %s %s" % (kind, day.date(), exc))
                flags = None
        row = dict(known)
        if flags is not None:
            row.update((code, flags.get(code) is True) for code in wanted)
            if day in keep:
                store[day] = row
        rows[day] = dict((code, row.get(code, False)) for code in codes)
    return pd.DataFrame.from_dict(rows, orient="index").reindex(index=dates, columns=codes).fillna(False).astype(bool)


def universe_panel(codes, dates, calendar, traded, opened, excluded):
    """sh_main membership: traded, not ST or delisting that day, more than 60 open days since listing (inclusive)."""
    position = calendar.searchsorted(dates)
    columns = {}
    for code in codes:
        listed = opened.get(code, pd.NaT)
        start = calendar.searchsorted(listed) if listed == listed else 0
        columns[code] = (position - start + 1) > NEW_LISTING_EXCLUDED_DAYS
    frame = pd.DataFrame(columns, index=dates).reindex(columns=codes).fillna(False).astype(bool)
    return frame & traded & ~excluded


def build_inputs(end, days, log=print, codes=None, status_days=None, cache=None):
    """jq240 inputs for sh_main (or ``codes``) over the ``days`` trading days ending at ``end`` (YYYYMMDD).

    ``status_days`` limits the per-day ST lookups to the last that many days (earlier days use the first looked-up
    day's flags); None looks up every day. ``cache``: a dict kept between calls; the per-day valuation and status
    answers of earlier days are taken from it (the slow part of a cold run) and new ones are added.
    """
    began = time.time()
    calendar = trading_calendar(end)
    dates = calendar[-days:]
    codes = list(codes) if codes is not None else sh_main_codes(end)
    every = all_a_codes(end)
    log("inputs.codes", "%d sh_main, %d all-A" % (len(codes), len(every)))
    log("inputs.dates", "%s..%s (%d)" % (dates[0].date(), dates[-1].date(), len(dates)))
    panels = price_panels(codes, dates, end, calendar)
    log("inputs.bars_seconds", round(time.time() - began, 2))
    opened = listing_dates(every)
    start = calendar[max(calendar.searchsorted(dates[0]) - 1, 0)]
    window = calendar[(calendar >= start) & (calendar <= dates[-1])]
    valuation = valuation_panels(every, window, ["total_shares", "a_floats"], log, cache)
    log("inputs.valuation_seconds", round(time.time() - began, 2))
    total = valuation["total_shares"].reindex(index=dates, columns=codes)
    floats = valuation["a_floats"].reindex(index=dates, columns=codes)
    raw_close = panels.pop("raw_close")
    raw_volume = panels.pop("raw_volume")
    quotes = dict((name, panels.pop(name)) for name in ("raw_open", "raw_pre_close", "factor"))
    inputs = dict(panels)
    inputs["quotes"] = quotes
    inputs["cap"] = raw_close * total
    inputs["basic_close"] = raw_close
    inputs["basic_total_share"] = total.where(raw_close.notna())
    inputs["basic_circ_mv"] = raw_close * floats
    # Tushare's turnover_rate: traded shares / circulating shares, in percent.
    inputs["basic_turnover_rate"] = (raw_volume / floats.where(floats > 0) * 100.0).where(raw_close.notna())
    first_year = max(2005, dates[0].year - FUNDAMENTAL_YEARS_BACK)
    fundamentals = fundamentals_frame(codes, first_year, _day(end).year, log)
    inputs["fundamentals"] = fundamentals
    log("inputs.fundamental_rows", len(fundamentals))
    log("inputs.fundamentals_seconds", round(time.time() - began, 2))
    grid = QuarterGrid(prepare_fundamentals(fundamentals), dates, pd.Index(codes))  # noqa: F821
    profit = grid.panel(grid.ttm("n_income_attr_p"))
    inputs["basic_pe_ttm"] = (inputs["cap"] / profit.where(profit > 0)).where(raw_close.notna())
    mkt, count = market_return(every, dates, end, calendar, opened, valuation["a_floats"])
    inputs["mkt"] = mkt
    last = count.iloc[-1] if len(count) else 0
    log("inputs.mkt_stocks_last", int(last) if last == last else 0)
    looked = dates if status_days is None else dates[-status_days:]
    excluded = status_panel(codes, looked, "ST", log, cache) | status_panel(codes, looked, "DELISTING", log, cache)
    excluded = excluded.reindex(index=dates).bfill().fillna(False).astype(bool)
    quotes["st"] = set(code for code in codes if excluded[code].iloc[-1])
    inputs["universe"] = universe_panel(codes, dates, calendar, raw_close.notna(), opened, excluded)
    log("inputs.universe_last", int(inputs["universe"].iloc[-1].sum()))
    log("inputs.seconds", round(time.time() - began, 2))
    return inputs


# Score a walk-forward LightGBM window inside QMT, where lightgbm is not installed: the window's inference steps
# (ProcessInf, ZScoreNorm with the fit-period statistics, Fillna 0) and the booster's trees, in numpy 1.19.
# The model dict comes from qmt/export_model.py; it holds no code.
import numpy as np


def prepare_model(model):
    """Turn the exported lists into numpy arrays once."""
    trees = []
    for tree in model["trees"]:
        trees.append({
            "feature": np.asarray(tree["feature"], dtype=np.int64),
            "threshold": np.asarray(tree["threshold"], dtype=np.float64),
            "left": np.asarray(tree["left"], dtype=np.int64),
            "right": np.asarray(tree["right"], dtype=np.int64),
            "leaf": np.asarray(tree["leaf"], dtype=np.float64),
        })
    return {
        "features": list(model["features"]),
        "mean": np.asarray(model["mean"], dtype=np.float32),
        "std": np.asarray(model["std"], dtype=np.float32),
        "trees": trees,
    }


def normalise(values, prepared):
    """Rows x features factor values of one day -> the float32 matrix the booster was trained on.

    +/-inf becomes the mean of the column's finite values that day (ProcessInf), then the fit-period z-score is applied
    in single precision, as the training panel was, and missing values become 0 (Fillna).
    """
    block = np.array(values, dtype=np.float32)
    infinite = np.isinf(block)
    if infinite.any():
        finite = np.where(infinite, np.nan, block)
        for column in np.nonzero(infinite.any(axis=0))[0]:
            kept = finite[:, column]
            kept = kept[~np.isnan(kept)]
            fill = kept.mean(dtype=np.float32) if len(kept) else np.float32(np.nan)
            block[infinite[:, column], column] = fill
    block = (block - prepared["mean"]) / prepared["std"]
    block[np.isnan(block)] = 0
    return block


def predict(prepared, matrix):
    """Sum of the trees' leaf values for each row of ``matrix`` (numerical splits, ``value <= threshold`` goes left).

    Child indices >= 0 are internal nodes; a negative child c is leaf ~c. LightGBM compares in double precision, and
    with missing type None it reads NaN as 0, which ``normalise`` has already done.
    """
    values = np.asarray(matrix, dtype=np.float64)
    rows = np.arange(len(values))
    total = np.zeros(len(values))
    for tree in prepared["trees"]:
        if len(tree["feature"]) == 0:
            total += tree["leaf"][0]
            continue
        node = np.zeros(len(values), dtype=np.int64)
        active = np.ones(len(values), dtype=bool)
        while active.any():
            current = node[active]
            goes_left = values[rows[active], tree["feature"][current]] <= tree["threshold"][current]
            node[active] = np.where(goes_left, tree["left"][current], tree["right"][current])
            active = node >= 0
        total += tree["leaf"][~node]
    return total


# Paper book for the live strategy: Qlib's TopkDropoutStrategy (topk, n_drop, method top/bottom, hold_thresh 1,
# only_tradable, risk_degree 1) traded at the next open by Qlib's SimulatorExecutor with RQuant's A-share costs.
# Amounts are Qlib's adjusted amounts (real shares / adjustment factor) and prices are adjusted prices, so a
# replay from the same book gives the same orders as RQuant's backtest. Pure pandas/numpy; no orders are placed.
import numpy as np
import pandas as pd

TRADE_UNIT = 100
COMMISSION = 0.0003
MIN_COMMISSION = 5.0
STAMP_TAX = 0.0005  # sells from 2023-08-28
# Qlib clips orders against cash with its own cost ratios before RQuant's cost model prices them.
OPEN_COST = COMMISSION
CLOSE_COST = COMMISSION + 0.001
SELL, BUY = 0, 1


def trade_cost(value, sell):
    if value <= 1e-5:
        return 0.0
    cost = max(MIN_COMMISSION, value * COMMISSION)
    return cost + (value * STAMP_TAX if sell else 0.0)


def round_amount(amount, factor):
    """Qlib's round_amount_by_trade_unit: whole lots of real shares, back in adjusted amount."""
    return (amount * factor + 0.1) // TRADE_UNIT * TRADE_UNIT / factor


class Day(object):
    """One trading day's quotes: adjusted open/close and adjustment factor per code, and the open-limit flags.

    A code without a finite close is suspended, as in Qlib.
    """

    def __init__(self, date, open_, close, factor, limit_buy, limit_sell):
        self.date = date
        self.open = open_
        self.close = close
        self.factor = factor
        self.limit_buy = limit_buy
        self.limit_sell = limit_sell

    def suspended(self, code):
        value = self.close.get(code, np.nan)
        return not (value == value)

    def tradable(self, code, direction=None):
        if self.suspended(code):
            return False
        buy, sell = bool(self.limit_buy.get(code, False)), bool(self.limit_sell.get(code, False))
        if direction is None:
            return not (buy or sell)
        return not (buy if direction == BUY else sell)

    def deal_price(self, code):
        value = self.open.get(code, np.nan)
        if not (value == value) or value <= 1e-08:
            value = self.close.get(code, np.nan)
        return value


class Book(object):
    def __init__(self, cash, amount=None, price=None, count=None):
        self.cash = float(cash)
        self.amount = dict(amount or {})
        self.price = dict(price or {})
        self.count = dict(count or {})

    def copy(self):
        return Book(self.cash, self.amount, self.price, self.count)

    def value(self):
        return self.cash + sum(self.amount[code] * self.price[code] for code in self.amount)

    def deal(self, code, direction, amount, day):
        """Qlib Exchange.deal_order against this book; returns (amount, price, value, cost), amount 0 if not dealt."""
        price = day.deal_price(code)
        factor = day.factor[code]
        if direction == SELL:
            held = self.amount.get(code, 0.0)
            if not np.isclose(amount, held):
                amount = round_amount(min(held, amount), factor)
            if self.cash + amount * price < max(amount * price * CLOSE_COST, MIN_COMMISSION):
                amount = 0.0
        else:
            value = amount * price
            if self.cash < max(value * OPEN_COST, MIN_COMMISSION):
                amount = 0.0
            elif self.cash < value + max(value * OPEN_COST, MIN_COMMISSION):
                amount = round_amount(min(_cash_limited_amount(price, self.cash), amount), factor)
            else:
                amount = round_amount(amount, factor)
        value = amount * price
        cost = trade_cost(value, direction == SELL)
        if value <= 1e-5:
            return 0.0, price, 0.0, 0.0
        if direction == SELL:
            left = self.amount[code] - amount
            if abs(left) < 1e-5:
                for table in (self.amount, self.price, self.count):
                    table.pop(code, None)
            else:
                self.amount[code] = left
            self.cash += value - cost
        else:
            if code not in self.amount:
                self.amount[code], self.price[code], self.count[code] = amount, price, 0
            else:
                self.amount[code] += amount
            self.cash -= value + cost
        return amount, price, value, cost

    def close_day(self, day):
        """Mark holdings to the close (suspended ones keep their price) and count one more held day."""
        for code in self.amount:
            if not day.suspended(code):
                self.price[code] = day.close[code]
            self.count[code] = self.count.get(code, 0) + 1


def _cash_limited_amount(price, cash):
    if cash < MIN_COMMISSION:
        return 0.0
    if cash >= MIN_COMMISSION / OPEN_COST + MIN_COMMISSION:
        return cash / (1 + OPEN_COST) / price
    return (cash - MIN_COMMISSION) / price


def ranked(scores):
    """Codes by score, highest first; ties by code, missing scores last.

    Qlib sorts with an unstable quicksort, so the order of equal scores depends on the numpy build; a short model
    (few trees) gives many equal scores, so the paper book fixes the order instead.
    """
    scores = scores.sort_index()
    return scores.index[np.argsort(-scores.values, kind="mergesort")]


def decide(scores, book, day, topk, n_drop):
    """Qlib TopkDropoutStrategy.generate_trade_decision for ``day``.

    ``scores`` is the previous trading day's prediction (a Series indexed by code); ``day`` holds the quotes the
    tradability checks and the sell simulation use. Ties in score are ordered by ``ranked``. Returns (sells, buys):
    sells and buys as (code, adjusted amount) in the order Qlib places them.
    """
    scores = scores.dropna()

    def first_n(codes, n, reverse=False):
        picked = []
        for code in (reversed(list(codes)) if reverse else codes):
            if day.tradable(code):
                picked.append(code)
                if len(picked) >= n:
                    break
        return picked[::-1] if reverse else picked

    temp = book.copy()
    current = list(temp.amount)
    last = ranked(scores.reindex(current))
    others = ranked(scores[~scores.index.isin(last)])
    today = first_n(others, n_drop + topk - len(last))
    comb = ranked(scores.reindex(last.union(pd.Index(today))))
    sell = last[last.isin(first_n(comb, n_drop, reverse=True))]
    buy = today[: len(sell) + topk - len(last)]
    sells = []
    for code in current:
        if not day.tradable(code, SELL):
            continue
        if code in sell:
            if temp.count.get(code, 0) < 1:
                continue
            amount = temp.amount[code]
            sells.append((code, amount))
            temp.deal(code, SELL, amount, day)
    cash = temp.cash
    value = cash / len(buy) if len(buy) > 0 else 0
    buys = []
    for code in buy:
        if not day.tradable(code, BUY):
            continue
        amount = round_amount(value / day.deal_price(code), day.factor[code])
        buys.append((code, amount))
    return sells, buys


def trade_day(scores, book, day, topk, n_drop):
    """Decide with the previous day's ``scores``, execute at ``day``'s open, mark at its close. Returns the fills."""
    sells, buys = decide(scores, book, day, topk, n_drop)
    fills = []
    for direction, orders in ((SELL, sells), (BUY, buys)):
        for code, amount in orders:
            dealt, price, value, cost = book.deal(code, direction, amount, day)
            if dealt > 0:
                fills.append({"date": day.date, "code": code, "side": "sell" if direction == SELL else "buy",
                              "amount": dealt, "shares": dealt * day.factor[code], "price": price,
                              "value": value, "cost": cost})
    book.close_day(day)
    return fills


# From qmt/runtime/paper_shell.py
COMPLETE_SHARE = 0.9

def complete_days(inputs, now):
    """Trading days with finished daily bars: today is dropped while its session is still open (before 15:00), and
    so are latest days whose bars only some stocks have (QMT lists today in the calendar before its daily bars
    arrive, and a download cut short leaves the rest of the stocks a day behind)."""
    close = inputs['close']
    counts = close.notna().sum(axis=1)
    dates = close.index[(counts > 0).values]
    if len(dates) and dates[-1] == pd.Timestamp(now[:8]) and (now[8:] < '1500'):
        dates = dates[:-1]
    while len(dates) > 1 and counts[dates[-1]] < COMPLETE_SHARE * counts[dates[-11:-1]].max():
        dates = dates[:-1]
    return dates

def limit_price(pre_close, pct):
    """Exchange limit price: pre-close times (1 +/- pct), rounded half up to the fen."""
    return np.floor(pre_close * pct * 100.0 + 0.5 + 1e-06) / 100.0

def daily_scores(inputs, window):
    """Model scores of every universe member on each day of ``window``, keyed by day."""
    calculator = JQFactors(inputs)
    prepared = prepare_model(MODEL)
    panels = {}
    for ordinal, name in enumerate(JQ240_NAMES, 1):
        key = 'jq_%03d' % ordinal
        if key in prepared['features']:
            panels[key] = calculator.calculate(name).reindex(window)
    missing = [name for name in prepared['features'] if name not in panels]
    if missing:
        raise ValueError('model needs factors the calculator lacks: %s' % ','.join(missing))
    scores = {}
    for date in window:
        member = inputs['universe'].loc[date]
        codes = sorted((code for code, inside in zip(member.index, member.values) if inside))
        if not codes:
            continue
        matrix = np.column_stack([panels[name].loc[date].reindex(codes).values for name in prepared['features']])
        scores[date] = pd.Series(predict(prepared, normalise(matrix, prepared)), index=codes)
    return scores

# From qmt/runtime/live_shell.py
def masked(account):
    return '*' * max(len(account) - 4, 0) + account[-4:]

def live_sell(C, plan, account, tag, auction=False):
    cash, positions = read_account(account)
    held = sorted(positions)
    codes = sorted(set(plan['scores'].index) | set(held))
    day, limits = tick_day(C, codes, plan['st'], auction)
    if sum((1 for code in plan['scores'].index if code in day.open)) < 0.5 * len(plan['scores']):
        return None
    value = sum((positions[code][0] * day.close[code] for code in held if day.close[code] == day.close[code]))
    capital = LIVE_CAPITAL if LIVE_CAPITAL > 0 else cash + value
    budget = max(0.0, min(cash, capital - value))
    rq_log('live.account', '%s cash %.2f holdings %d value %.2f budget %.2f at %s' % (masked(account), cash, len(held), value, budget, beijing_clock()[8:]))
    book = Book(budget, dict(((code, float(positions[code][0])) for code in held)), dict(((code, day.close[code]) for code in held)), dict(((code, 1 if positions[code][1] > 0 else 0) for code in held)))
    sells, buys = decide(plan['scores'], book, day, LIVE_TOPK, LIVE_N_DROP)
    sold, sent, proceeds = (0.0, 0, 0.0)
    kept = dict(((code, positions[code][0]) for code in held))
    for code, shares in sells:
        sellable = positions[code][1]
        price = limits[code][1] if auction else max(limits[code][1], round(day.close[code] * (1 - LIVE_SLIP), 2))
        if sellable > 0:
            send(C, account, 'sell', code, sellable, price, tag)
            sent += 1
            if day.close[code] == day.close[code]:
                proceeds += sellable * day.close[code] * (1 - CLOSE_COST)
            sold += sellable * price * (1 - CLOSE_COST)
            kept[code] -= sellable
            if kept[code] <= 0:
                kept.pop(code)
    value_after = sum((kept[code] * day.close[code] for code in kept if day.close[code] == day.close[code]))
    return {'day': day, 'limits': limits, 'buys': buys, 'sold': sold, 'kept': kept, 'value_after': value_after, 'capital': capital, 'sells': sent, 'auction': auction, 'proceeds': proceeds}

def _lots(shares):
    return int(shares // TRADE_UNIT * TRADE_UNIT)

def live_buy(C, sold, account, tag):
    """New names as the backtest sizes them, at most one slot (the strategy's money / LIVE_TOPK) each; then the idle
    cash goes out one lot at a time, always to the name furthest below its share, up to LIVE_FILL_MAX slots a name.
    With ~6,000 yuan slots and 100-share lots of up to 5,000 yuan, flooring each name to a slot left a quarter of the
    money idle."""
    cash, _ = read_account(account)
    if LIVE_DRY_RUN and (not sold.get('auction')):
        cash += sold['sold']
    day, limits, kept = (sold['day'], sold['limits'], sold['kept'])
    budget = max(0.0, min(cash, sold['capital'] - sold['value_after']))
    slot = (sold['value_after'] + budget) / LIVE_TOPK
    ceiling = LIVE_MAX_ORDER * sold['capital'] / LIVE_TOPK
    slip = LIVE_AUCTION_BUY if sold.get('auction') else LIVE_SLIP

    def price_of(code):
        return min(limits[code][0], round(day.close[code] * (1 + slip), 2))
    orders = [(code, min(amount, slot / price_of(code)), price_of(code)) for code, amount in sold['buys']]
    planned = sum((amount * price for _, amount, price in orders)) * (1 + OPEN_COST)
    scale = min(1.0, budget / planned) if planned > 0 else 0.0
    rq_log('live.buy_budget', '%.2f planned %.2f scale %.3f slot %.0f' % (budget, planned, scale, slot))
    left = budget
    shares = {}
    for code, amount, price in orders:
        lot = TRADE_UNIT * price * (1 + OPEN_COST)
        count = _lots(amount * scale)
        if count <= 0 and TRADE_UNIT * price <= LIVE_FIRST_LOT_MAX * slot and (lot <= left):
            count = TRADE_UNIT
        if count <= 0:
            rq_log('live.skip_buy', '%s one lot (%.0f yuan) is too dear for its share of the cash' % (code, TRADE_UNIT * price))
            continue
        shares[code] = count
        left -= count * price * (1 + OPEN_COST)
    coming = sold.get('proceeds', 0.0) if sold.get('auction') else 0.0
    reserve = max(0.0, LIVE_N_DROP * slot - coming) if LIVE_AUCTION else 0.0
    rq_log('live.reserve', "%.0f kept for tomorrow's auction buys" % reserve)
    held = dict(((code, kept[code] * day.close[code]) for code in kept if LIVE_TOPUP and day.close[code] == day.close[code] and day.tradable(code, BUY)))
    names = set(held) | set(shares)
    added = dict(((code, 0) for code in names))

    def value(code):
        return held.get(code, 0.0) + (shares.get(code, 0) + added[code]) * price_of(code)
    while True:
        best = None
        for code in names:
            price = price_of(code)
            lot = TRADE_UNIT * price * (1 + OPEN_COST)
            if lot > left - reserve or value(code) + TRADE_UNIT * price > LIVE_FILL_MAX * slot:
                continue
            if best is None or (value(code), code) < (value(best), best):
                best = code
        if best is None:
            break
        added[best] += TRADE_UNIT
        left -= TRADE_UNIT * price_of(best) * (1 + OPEN_COST)
    for code, amount, price in orders:
        count = shares.get(code, 0) + added.get(code, 0)
        if count <= 0:
            continue
        if count * price > ceiling:
            rq_log('live.skip_buy', '%s order %.0f yuan above the %.0f ceiling' % (code, count * price, ceiling))
            continue
        send(C, account, 'buy', code, count, price, tag)
    for code in sorted(held, key=lambda name: (held[name], name)):
        count = added.get(code, 0)
        if count and count * price_of(code) >= LIVE_TOPUP_MIN * slot:
            send(C, account, 'topup', code, count, price_of(code), tag)

# jq240 + LightGBM live trading in Guojin PTrade (the trading module: \u91cf\u5316 -> \u4ea4\u6613). Paste the whole generated file
# (ptrade/generated/jq240_ptrade_live.py) into a new PTrade strategy, daily frequency, and start a trade with it.
#
# PTrade runs the strategy on the broker's servers and leaves it running from day to day. Each trading day:
# * LIVE_PLAN_AT (08:00 Beijing) builds the jq240 inputs from PTrade's data through the last finished session and
#   scores sh_main with the exported LightGBM window. The first run after a start takes about 20 minutes; the per-day
#   lookups stay in memory, so later days take a few minutes. It also plans at once when the trade is started.
# * LIVE_AUCTION_AT (09:21) decides like the backtest's TopkDropoutStrategy (top LIVE_TOPK, drop at most LIVE_N_DROP)
#   against the real holdings and the previous close, and sends the sells at the limit-down price and the buys at
#   most LIVE_AUCTION_BUY above the previous close, so the opening auction fills both at the open. Buys only use the
#   cash on hand before the auction, so the account keeps about LIVE_N_DROP slots in cash for the next day.
# * If the plan was not ready for the auction: sells at LIVE_SELL_AT and buys at LIVE_BUY_AT after the open, as
#   marketable limit orders.
# It trades at most once a day, and not at all on a day the account already has orders for sh_main stocks.
#
# LIVE_DRY_RUN = True (the default) sends nothing: it logs the orders it would send, once at start and then at each
# auction. Set it to False only after a dry run looks right. The account is the one the PTrade login trades; nothing
# about it is written here.
LIVE_DRY_RUN = True
LIVE_CAPITAL = 0  # the most the strategy may hold (holdings at market plus cash); 0 = all its holdings and cash
LIVE_TOPK = 30
LIVE_N_DROP = 3
LIVE_KEEP = set()  # sh_main codes the strategy must leave alone, e.g. set(["600000.SS"])
LIVE_AUCTION = True
LIVE_PLAN_AT = "08:00"
LIVE_AUCTION_AT = "09:21"  # orders sent from 09:20 on cannot be cancelled, so the auction keeps them
LIVE_SELL_AT = "09:31"
LIVE_BUY_AT = "09:32"
LIVE_AUCTION_BUY = 0.03  # auction buy limit above the previous close (the cash it ties up); above it, no fill at the open
LIVE_SLIP = 0.01  # after the open: limit price offset from the last price; capped at the daily limit
LIVE_MAX_ORDER = 2.5  # no single buy above this many equal slots (strategy money / LIVE_TOPK)
LIVE_FILL_MAX = 1.3  # idle cash tops today's buys up lot by lot, to at most this many slots each
LIVE_TOPUP = False  # False: only today's new buys get the idle cash; True: held names are topped up too
LIVE_FIRST_LOT_MAX = 1.5  # a new name whose one lot is above a slot is still bought if the lot is under this
LIVE_TOPUP_MIN = 0.2  # top-ups of a held name under this many slots are not sent (5 yuan minimum commission)
LIVE_DAYS = 1100  # trading days of history the factors are computed on (as the QMT strategy)
LIVE_TAG = "[RQ]"
SNAPSHOT_CHUNK = 300
HALTED = ("HALT", "SUSP", "STOPT", "DELISTED")
_pt = {"context": None, "plan": None, "planning": False, "sold": None, "done": None, "dry": set(), "cache": {}}


def rq_log(key, value=""):
    log.info("%s %s=%s" % (LIVE_TAG, key, value))  # noqa: F821 - PTrade's logger


def beijing_clock():
    """Beijing wall-clock time as YYYYMMDDHHMMSS, whatever the server's time zone."""
    return time.strftime("%Y%m%d%H%M%S", time.gmtime(time.time() + 8 * 3600))


def _where(exc):
    """Where an exception came from, innermost last, without the standard traceback helpers (PTrade may refuse them)."""
    spots, frame = [], exc.__traceback__
    while frame is not None:
        spots.append("%s:%d" % (frame.tb_frame.f_code.co_name, frame.tb_lineno))
        frame = frame.tb_next
    return "%s: %s at %s" % (type(exc).__name__, exc, " > ".join(spots[-5:]))


def managed(code):
    return code.startswith("60") and code.endswith(".SS") and code not in LIVE_KEEP


def account_label():
    try:
        return str(get_user_name() or "ptrade")  # noqa: F821
    except Exception:
        return "ptrade"


def read_account(account):
    """(available cash, {code: (shares, sellable shares)}) for the strategy's sh_main codes."""
    portfolio = _pt["context"].portfolio
    positions = {}
    for code, position in (portfolio.positions or {}).items():
        shares = int(getattr(position, "amount", 0) or 0)
        if shares > 0 and managed(code):
            positions[code] = (shares, int(getattr(position, "enable_amount", 0) or 0))
    return float(portfolio.cash), positions


def sent_today():
    """Today's orders in the account for sh_main stocks (any source), as get_all_orders lists them."""
    rows = get_all_orders() or []  # noqa: F821
    return [row for row in rows if managed(str(row.get("symbol", "")))]


def tick_day(C, codes, st, auction=False):
    """paper.Day from PTrade's snapshots: open and last price in yuan, factor 1, open-limit flags, and the exchange's
    limit prices. In the auction the previous close stands for both prices and no code opens at a limit; outside
    trading hours (a dry run) a stock without a last price uses its previous close."""
    snaps = {}
    for chunk in _chunks(list(codes), SNAPSHOT_CHUNK):
        snaps.update(get_snapshot(chunk) or {})  # noqa: F821
    open_, last, factor, limit_buy, limit_sell, limits = {}, {}, {}, {}, {}, {}
    for code in codes:
        snap = snaps.get(code) or {}
        pre, price, opened = (float(snap.get(key) or 0.0) for key in ("preclose_px", "last_px", "open_px"))
        if auction or price <= 0:
            price = pre
        if auction or opened <= 0:
            opened = price
        factor[code] = 1.0
        if str(snap.get("trade_status", "")) in HALTED or price <= 0 or pre <= 0:
            last[code] = np.nan
            continue
        pct = 0.05 if code in st else 0.10
        up = float(snap.get("up_px") or 0.0) or float(limit_price(pre, 1 + pct))
        down = float(snap.get("down_px") or 0.0) or float(limit_price(pre, 1 - pct))
        open_[code], last[code], limits[code] = opened, price, (up, down)
        limit_buy[code] = (not auction) and round(opened, 2) >= round(up, 2)
        limit_sell[code] = (not auction) and round(opened, 2) <= round(down, 2)
    return Day(None, open_, last, factor, limit_buy, limit_sell), limits


def send(C, account, side, code, shares, price, tag):
    rq_log("live.%s" % ("dry_" + side if LIVE_DRY_RUN else side), "%s %d shares limit %.2f (about %.0f yuan)" % (
        code, shares, price, shares * price))
    if LIVE_DRY_RUN:
        return
    amount = -int(shares) if side == "sell" else int(shares)
    if order(code, amount, limit_price=round(float(price), 2)) is None:  # noqa: F821
        rq_log("live.order_failed", "%s %d" % (code, amount))


def previous_session(today):
    """The last trading day before ``today`` (YYYYMMDD), and whether ``today`` is a trading day."""
    days = trading_calendar(today)
    stamp = pd.Timestamp(today)
    before = days[days < stamp]
    return (before[-1] if len(before) else None), bool(len(days) and days[-1] == stamp)


def live_plan():
    """Scores of the last finished session, or None (logged) when the data is not current."""
    began = time.time()
    clock = beijing_clock()
    inputs = build_inputs(clock[:8], LIVE_DAYS, rq_log, cache=_pt["cache"])
    listed = inputs["close"].index
    counts = inputs["close"].notna().sum(axis=1)
    rq_log("live.bars", ",".join("%s:%d" % (day.strftime("%Y%m%d"), counts[day]) for day in listed[-3:]))
    dates = complete_days(inputs, clock[:12])
    today = pd.Timestamp(clock[:8])
    if not len(dates):
        rq_log("live.error", "no trading day with daily bars")
        return None
    last = dates[-1]
    rq_log("live.data_through", last.strftime("%Y%m%d"))
    missing = listed[(listed > last) & (listed < today)]
    if len(missing):
        rq_log("live.error", "daily bars of %s are missing" % ",".join(day.strftime("%Y%m%d") for day in missing))
        return None
    scores = daily_scores(inputs, pd.DatetimeIndex([last]))[last]
    rq_log("live.model", "%s year=%s" % (MODEL["run"], MODEL["prediction_year"]))
    rq_log("live.top%d" % LIVE_TOPK, ",".join(to_rquant(code) for code in ranked(scores)[:LIVE_TOPK]))
    rq_log("live.plan_seconds", round(time.time() - began, 2))
    return {"date": last, "scores": scores, "st": inputs["quotes"]["st"], "made": clock[:8]}


def rq_prepare(context):
    """Plan for the next session unless today's plan is in hand (or another job is making it)."""
    _pt["context"] = context
    today = beijing_clock()[:8]
    plan = _pt["plan"]
    if (plan is not None and plan["made"] == today) or _pt["planning"]:
        return
    _pt["planning"] = True
    try:
        _pt["plan"] = live_plan()
    except Exception as exc:
        rq_log("live.error", _where(exc))
    finally:
        _pt["planning"] = False


def _ready_plan(today):
    """Today's plan when it scores the session before today, else None (logged)."""
    plan = _pt["plan"]
    if plan is None:
        rq_log("live.skip", "no plan yet (still planning: %s)" % _pt["planning"])
        return None
    previous, trading = previous_session(today)
    if not trading:
        rq_log("live.skip", "%s is not a trading day" % today)
        return None
    if previous is None or plan["date"] != previous:
        rq_log("live.skip", "the plan scores %s, not the last session %s" % (
            plan["date"].strftime("%Y%m%d"), previous.strftime("%Y%m%d") if previous is not None else "?"))
        return None
    return plan


def rq_trade(context, mode):
    """mode 'auction' (sells and buys at once), 'sell' (after the open) or 'dry' (log only, at start)."""
    _pt["context"] = context
    clock = beijing_clock()
    today = clock[:8]
    if _pt["done"] == today or getattr(g, "rq_done", None) == today:  # noqa: F821
        return
    if LIVE_DRY_RUN and ((today, mode) in _pt["dry"] or (mode == "sell" and (today, "auction") in _pt["dry"])):
        return
    if mode != "dry":
        plan = _ready_plan(today)
    else:
        plan = _pt["plan"]
    if plan is None:
        return
    if not LIVE_DRY_RUN:
        orders = sent_today()
        if orders:
            rq_log("live.skip", "the account already has %d sh_main orders today: no orders" % len(orders))
            _pt["done"] = g.rq_done = today  # noqa: F821
            return
    account = account_label()
    sold = live_sell(context, plan, account, today, mode == "auction")
    if sold is None:
        rq_log("live.error", "no quotes for the planned stocks")
        return
    if LIVE_DRY_RUN:
        _pt["dry"].add((today, mode))
    if mode == "sell" and not LIVE_DRY_RUN:
        _pt["sold"] = (today, sold)
        return
    live_buy(context, sold, account, today)
    rq_log("live.done", "dry run, nothing sent" if LIVE_DRY_RUN else "orders sent at %s" % clock[8:])
    if not LIVE_DRY_RUN:
        _pt["done"] = g.rq_done = today  # noqa: F821


def rq_auction(context):
    if LIVE_AUCTION:
        try:
            rq_trade(context, "auction")
        except Exception as exc:
            rq_log("live.error", _where(exc))


def rq_after_open_sell(context):
    try:
        rq_trade(context, "sell")
    except Exception as exc:
        rq_log("live.error", _where(exc))


def rq_after_open_buy(context):
    _pt["context"] = context
    today = beijing_clock()[:8]
    held = _pt["sold"]
    if held is None or held[0] != today or _pt["done"] == today:
        return
    try:
        live_buy(context, held[1], account_label(), today)
        rq_log("live.done", "orders sent after the open")
    except Exception as exc:
        rq_log("live.error", _where(exc))
    _pt["done"] = g.rq_done = today  # noqa: F821


def initialize(context):
    _pt["context"] = context
    rq_log("live", "start dry_run=%s auction=%s topk=%d n_drop=%d" % (LIVE_DRY_RUN, LIVE_AUCTION, LIVE_TOPK,
                                                                      LIVE_N_DROP))
    run_daily(context, rq_prepare, time=LIVE_PLAN_AT)  # noqa: F821
    run_daily(context, rq_auction, time=LIVE_AUCTION_AT)  # noqa: F821
    run_daily(context, rq_after_open_sell, time=LIVE_SELL_AT)  # noqa: F821
    run_daily(context, rq_after_open_buy, time=LIVE_BUY_AT)  # noqa: F821


def before_trading_start(context, data):
    """Runs when the trade starts and at 09:10 each day: plans if LIVE_PLAN_AT did not; a dry run logs its orders."""
    rq_prepare(context)
    if LIVE_DRY_RUN:
        moment = beijing_clock()[8:12]
        if not ("0915" <= moment < "0935"):  # the auction and after-open jobs log their own dry run
            try:
                rq_trade(context, "dry")
            except Exception as exc:
                rq_log("live.error", _where(exc))


def handle_data(context, data):
    pass

